/* THLC PDF Merge Center — all processing happens locally in the browser. */

const LICENSE_STORAGE_KEY = 'thlc-license-v1';
const DEFAULT_LICENSE_B64 = "";
const DEFAULT_LICENSE_NAME = "THLC_Customs_Free_Zone_Business_Operation_License_Y_2024.pdf";

let exportEntry = null;   // {name, file}
let goodsControl = null;  // {name, file}
let scanFiles = [];       // {file, path, lowerPath, name}
let reviewQueue = [];     // ok slots only, draggable
let missingQueue = [];    // missing slots, need manual upload
let manualCarryOver = {}; // label -> {name, file}
let licenseDoc = null;    // {filename, base64}
let dragSrcIdx = null;

/* ================= Shipment table ================= */
const shipmentRows = document.getElementById('shipmentRows');

function makeShipRow(cw1 = '', pk = '') {
  const tr = document.createElement('tr');
  tr.innerHTML = `
    <td><input type="text" class="cw1" value="${cw1}" placeholder="e.g. SRKL0081363"></td>
    <td><input type="text" class="pk" value="${pk}" placeholder="PK No."></td>
    <td class="rm"><button title="Remove row">✕</button></td>
  `;
  tr.querySelector('.rm button').addEventListener('click', () => {
    tr.remove();
    ensureRow();
    onShipmentsChanged();
  });
  tr.querySelector('.cw1').addEventListener('input', onShipmentsChanged);
  tr.querySelector('.pk').addEventListener('input', onShipmentsChanged);
  tr.querySelector('.cw1').addEventListener('paste', e => handleShipPaste(e, tr, 'cw1'));
  tr.querySelector('.pk').addEventListener('paste', e => handleShipPaste(e, tr, 'pk'));
  return tr;
}

function ensureRow() {
  if (!shipmentRows.children.length) shipmentRows.appendChild(makeShipRow());
}

function handleShipPaste(e, currentTr, startCol) {
  const text = (e.clipboardData || window.clipboardData).getData('text');
  if (!text || (!text.includes('\t') && !text.includes('\n'))) return; // let normal single paste happen
  e.preventDefault();
  const rows = text.replace(/\r/g, '').split('\n').filter(r => r.length);
  let startIdx = Array.from(shipmentRows.children).indexOf(currentTr);
  if (startIdx < 0) startIdx = 0;

  rows.forEach((rowText, i) => {
    const cols = rowText.split('\t');
    let tr = shipmentRows.children[startIdx + i];
    if (!tr) { tr = makeShipRow(); shipmentRows.appendChild(tr); }
    if (startCol === 'cw1') {
      tr.querySelector('.cw1').value = (cols[0] || '').trim();
      if (cols.length > 1) tr.querySelector('.pk').value = (cols[1] || '').trim();
    } else {
      tr.querySelector('.pk').value = (cols[0] || '').trim();
    }
  });
  onShipmentsChanged();
}

function getShipments() {
  return Array.from(shipmentRows.children)
    .map(tr => ({ cw1: tr.querySelector('.cw1').value.trim(), pk: tr.querySelector('.pk').value.trim() }))
    .filter(r => r.cw1);
}

function onShipmentsChanged() {
  ensureRow();
  updateStepper();
  if (scanFiles.length) buildQueues();
}

document.getElementById('addShipment').addEventListener('click', () => shipmentRows.appendChild(makeShipRow()));
document.getElementById('clearShipments').addEventListener('click', () => {
  // Reset the shipment table itself
  shipmentRows.innerHTML = '';
  ensureRow();

  // Everything downstream of the shipment list is now stale — clear it all rather
  // than leaving orphaned scan results / dropped files that no longer match anything.
  exportEntry = null;
  goodsControl = null;
  scanFiles = [];
  reviewQueue = [];
  missingQueue = [];
  manualCarryOver = {};

  // Reset Export Entry / Goods Control List dropzones back to empty
  [exportZone, gclZone].forEach(z => z.classList.remove('filled'));
  document.getElementById('exportList').textContent = '';
  document.getElementById('gclList').textContent = '';
  document.getElementById('exportCount').textContent = '0';
  document.getElementById('gclCount').textContent = '0';
  document.getElementById('exportInput').value = '';
  document.getElementById('gclInput').value = '';

  // Reset folder scan panel and its file input (so the same folder can be re-picked)
  folderInput.value = '';
  scanPanel.className = 'scan-panel';
  scanTitle.textContent = 'No folder selected';
  scanText.textContent = 'Select the main shipment folder to scan filenames only.';

  renderReview();
  renderMissing();
  updateStepper();
  setStatus('');
});
ensureRow();

/* ================= Export Entry / Goods Control List dropzones ================= */
function wireDropzone(zoneEl, inputEl, listEl, countEl, onSet) {
  zoneEl.addEventListener('click', () => inputEl.click());
  zoneEl.addEventListener('dragover', e => { e.preventDefault(); zoneEl.classList.add('dragover'); });
  zoneEl.addEventListener('dragleave', () => zoneEl.classList.remove('dragover'));
  zoneEl.addEventListener('drop', e => {
    e.preventDefault(); zoneEl.classList.remove('dragover');
    const f = e.dataTransfer.files[0];
    if (f) onSet(f);
  });
  inputEl.addEventListener('change', e => { if (e.target.files[0]) onSet(e.target.files[0]); });

  function apply(f) {
    zoneEl.classList.add('filled');
    listEl.textContent = '✓ ' + f.name;
    countEl.textContent = '1';
  }
  return apply;
}

const exportZone = document.querySelector('[data-input="exportInput"]');
const exportApply = wireDropzone(
  exportZone, document.getElementById('exportInput'),
  document.getElementById('exportList'), document.getElementById('exportCount'),
  f => { exportEntry = { name: f.name, file: f }; exportApplyUI(f); buildQueues(); updateStepper(); }
);
function exportApplyUI(f) { exportApply(f); }

const gclZone = document.querySelector('[data-input="gclInput"]');
const gclApply = wireDropzone(
  gclZone, document.getElementById('gclInput'),
  document.getElementById('gclList'), document.getElementById('gclCount'),
  f => { goodsControl = { name: f.name, file: f }; gclApply(f); buildQueues(); updateStepper(); }
);

/* ================= Folder scan (webkitdirectory) ================= */
const folderInput = document.getElementById('folderInput');
const scanPanel = document.getElementById('scanPanel');
const scanTitle = document.getElementById('scanTitle');
const scanText = document.getElementById('scanText');

folderInput.addEventListener('change', e => {
  const files = Array.from(e.target.files || []);
  const pdfs = files.filter(f => f.name.toLowerCase().endsWith('.pdf'));
  scanFiles = pdfs.map(f => ({
    file: f,
    path: f.webkitRelativePath || f.name,
    lowerPath: (f.webkitRelativePath || f.name).toLowerCase(),
    name: f.name
  }));
  const rootName = files.length && files[0].webkitRelativePath ? files[0].webkitRelativePath.split('/')[0] : '(folder)';
  scanPanel.className = 'scan-panel success';
  scanTitle.textContent = `Scanned "${rootName}"`;
  scanText.textContent = `Found ${scanFiles.length} PDF file(s). Matching against ${getShipments().length} shipment(s)...`;
  buildQueues();
  updateStepper();
});

/* ================= Matching logic ================= */
function folderSegments(lowerPath) { return lowerPath.split('/').slice(0, -1); }

// Must contain the target keyword AND "th", and must NOT be the sibling "CN" folder
// (real-world folders come in pairs like "CIPL TH" / "CIPL CN" — a naive "includes cipl"
// check matches both, which was pulling the wrong-country documents into the merge).
function isCiplTh(seg) { return seg.includes('cipl') && seg.includes('th') && !seg.includes('cn'); }
function isInvoiceAttachmentTh(seg) { return seg.includes('invoice') && seg.includes('attach') && !seg.includes('cn'); }

function findShipmentRootPaths(pk) {
  if (!pk) return [];
  const p = pk.toLowerCase();
  const roots = new Set();
  scanFiles.forEach(e => {
    const segs = folderSegments(e.lowerPath);
    const hit = segs.findIndex(s => s.includes(p));
    if (hit >= 0) roots.add(segs.slice(0, hit + 1).join('/'));
  });
  return [...roots];
}

function filesUnderRootInFolder(root, folderTest) {
  return scanFiles.filter(e => {
    if (root && !e.lowerPath.startsWith(root + '/')) return false;
    return folderSegments(e.lowerPath).some(folderTest);
  });
}

function matchCipl(cw1, pk) {
  const roots = findShipmentRootPaths(pk);
  if (roots.length) {
    for (const root of roots) {
      const found = filesUnderRootInFolder(root, isCiplTh);
      if (found.length) return found.slice(0, 2);
    }
  }
  const key = (pk || cw1 || '').toLowerCase();
  return scanFiles.filter(e => folderSegments(e.lowerPath).some(isCiplTh) && key && e.lowerPath.includes(key));
}

function matchInvoiceAttachment(cw1, pk) {
  const roots = findShipmentRootPaths(pk);
  if (roots.length) {
    for (const root of roots) {
      const found = filesUnderRootInFolder(root, isInvoiceAttachmentTh);
      if (found.length) return found.slice(0, 1);
    }
  }
  const key = (pk || cw1 || '').toLowerCase();
  return scanFiles.filter(e => folderSegments(e.lowerPath).some(isInvoiceAttachmentTh) && key && e.lowerPath.includes(key)).slice(0, 1);
}

function matchTwb(cw1) {
  const c = cw1.toLowerCase();
  return scanFiles.filter(e => (e.lowerPath.includes('road b') || e.lowerPath.includes('hawb')) && e.lowerPath.includes(c));
}

/* ================= Build review / missing queues ================= */
function buildQueues() {
  const prevCarry = {};
  reviewQueue.forEach(s => { if (s.manual) prevCarry[s.label] = { name: s.name, file: s.file }; });
  manualCarryOver = { ...manualCarryOver, ...prevCarry };

  const shipments = getShipments();
  const review = [];
  const missing = [];

  if (exportEntry) review.push({ id: crypto.randomUUID(), label: 'Export Entry (0409)', name: exportEntry.name, file: exportEntry.file });
  if (goodsControl) review.push({ id: crypto.randomUUID(), label: 'Goods Control List', name: goodsControl.name, file: goodsControl.file });

  shipments.forEach(({ cw1, pk }) => {
    const ciplFiles = matchCipl(cw1, pk);
    if (ciplFiles.length === 0) {
      for (let i = 1; i <= 2; i++) {
        const label = `CIPL TH #${i} — Shipment ${cw1}`;
        const carry = manualCarryOver[label];
        if (carry) review.push({ id: crypto.randomUUID(), label, name: carry.name, file: carry.file, manual: true });
        else missing.push({ id: crypto.randomUUID(), label });
      }
    } else {
      ciplFiles.forEach(f => {
        review.push({
          id: crypto.randomUUID(),
          label: `CIPL TH — Shipment ${cw1}${ciplFiles.length !== 2 ? ' (check count)' : ''}`,
          name: f.name, file: f.file, warn: ciplFiles.length !== 2
        });
      });
    }

    const invFiles = matchInvoiceAttachment(cw1, pk);
    if (invFiles.length === 0) {
      const label = `Invoice Attachment — Shipment ${cw1}`;
      const carry = manualCarryOver[label];
      if (carry) review.push({ id: crypto.randomUUID(), label, name: carry.name, file: carry.file, manual: true });
      else missing.push({ id: crypto.randomUUID(), label });
    } else {
      invFiles.forEach(f => review.push({ id: crypto.randomUUID(), label: `Invoice Attachment — Shipment ${cw1}`, name: f.name, file: f.file }));
    }

    const twbFiles = matchTwb(cw1);
    if (twbFiles.length === 0) {
      const label = `TWB — Shipment ${cw1}`;
      const carry = manualCarryOver[label];
      if (carry) review.push({ id: crypto.randomUUID(), label, name: carry.name, file: carry.file, manual: true });
      else missing.push({ id: crypto.randomUUID(), label });
    } else {
      twbFiles.forEach(f => {
        review.push({
          id: crypto.randomUUID(),
          label: `TWB — Shipment ${cw1}${twbFiles.length > 1 ? ' (multiple found)' : ''}`,
          name: f.name, file: f.file, warn: twbFiles.length > 1
        });
      });
    }
  });

  reviewQueue = review;
  missingQueue = missing;
  renderReview();
  renderMissing();
  updateStepper();
}

/* ================= Render review list ================= */
const reviewCard = document.getElementById('reviewCard');
const reviewListEl = document.getElementById('reviewList');
const summaryEl = document.getElementById('summary');

function renderReview() {
  reviewCard.classList.toggle('hidden', reviewQueue.length === 0 && missingQueue.length === 0);
  reviewListEl.innerHTML = '';
  reviewQueue.forEach((slot, i) => {
    const row = document.createElement('div');
    row.className = 'row';
    row.draggable = true;
    row.dataset.idx = i;
    row.innerHTML = `
      <span class="grip">⠿</span>
      <span class="idx">${i + 1}</span>
      <span class="meta"><div class="lbl">${slot.label}</div><div class="fn">${slot.name}</div></span>
      ${slot.warn ? '<span class="tag">check</span>' : ''}
      <button class="remove" title="Remove">✕</button>
    `;
    row.addEventListener('dragstart', () => { dragSrcIdx = i; row.classList.add('dragging'); });
    row.addEventListener('dragend', () => row.classList.remove('dragging'));
    row.addEventListener('dragover', e => e.preventDefault());
    row.addEventListener('drop', e => {
      e.preventDefault();
      if (dragSrcIdx === null || dragSrcIdx === i) return;
      const moved = reviewQueue.splice(dragSrcIdx, 1)[0];
      reviewQueue.splice(i, 0, moved);
      dragSrcIdx = null;
      renderReview();
    });
    row.querySelector('.remove').addEventListener('click', () => { reviewQueue.splice(i, 1); renderReview(); });
    reviewListEl.appendChild(row);
  });

  summaryEl.innerHTML = '';
  getShipments().forEach(({ cw1 }) => {
    const relatedMissing = missingQueue.filter(s => s.label.includes(`Shipment ${cw1}`)).length;
    const chip = document.createElement('span');
    chip.className = 'summary-chip ' + (relatedMissing === 0 ? 'ok' : 'issue');
    chip.textContent = relatedMissing === 0 ? `${cw1} complete` : `${cw1} missing ${relatedMissing}`;
    summaryEl.appendChild(chip);
  });
}

/* ================= Render missing list ================= */
const missingCard = document.getElementById('missingCard');
const missingListEl = document.getElementById('missingList');

function renderMissing() {
  missingCard.classList.toggle('hidden', missingQueue.length === 0);
  missingListEl.innerHTML = '';
  missingQueue.forEach((slot, i) => {
    const row = document.createElement('div');
    row.className = 'row droppable';
    row.innerHTML = `
      <span class="meta">${slot.label} — not found in the scanned folder<br><small>drop a PDF here, or</small></span>
      <button class="up">Browse…</button>
      <input type="file" accept="application/pdf,.pdf" hidden>
    `;
    const btn = row.querySelector('.up');
    const inp = row.querySelector('input');

    function acceptFile(f) {
      if (!f || (f.type !== 'application/pdf' && !f.name.toLowerCase().endsWith('.pdf'))) return;
      manualCarryOver[slot.label] = { name: f.name, file: f };
      missingQueue.splice(i, 1);
      reviewQueue.push({ id: crypto.randomUUID(), label: slot.label, name: f.name, file: f, manual: true });
      renderReview();
      renderMissing();
      updateStepper();
    }

    btn.addEventListener('click', () => inp.click());
    inp.addEventListener('change', e => acceptFile(e.target.files[0]));
    row.addEventListener('dragover', e => { e.preventDefault(); row.classList.add('dragover'); });
    row.addEventListener('dragleave', () => row.classList.remove('dragover'));
    row.addEventListener('drop', e => {
      e.preventDefault();
      row.classList.remove('dragover');
      acceptFile(e.dataTransfer.files[0]);
    });

    missingListEl.appendChild(row);
  });
}

/* ================= License (fixed, always last, locked) ================= */
async function loadLicense() {
  try {
    const res = await window.storage.get(LICENSE_STORAGE_KEY, false);
    licenseDoc = res && res.value ? JSON.parse(res.value) : null;
  } catch (e) { licenseDoc = null; }
  if (!licenseDoc) {
    licenseDoc = { filename: DEFAULT_LICENSE_NAME, base64: DEFAULT_LICENSE_B64 };
    try { await window.storage.set(LICENSE_STORAGE_KEY, JSON.stringify(licenseDoc), false); } catch (e) {}
  }
  document.getElementById('licenseName').textContent = `Always appended last · ${licenseDoc.filename}`;
}

document.getElementById('licenseInput').addEventListener('change', async e => {
  const f = e.target.files[0];
  if (!f) return;
  const b64 = await fileToBase64(f);
  licenseDoc = { filename: f.name, base64: b64 };
  try { await window.storage.set(LICENSE_STORAGE_KEY, JSON.stringify(licenseDoc), false); } catch (err) {}
  document.getElementById('licenseName').textContent = `Always appended last · ${f.name}`;
  setStatus('License replaced — this file will be used as the default from now on.', 'success');
});

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}
function base64ToBytes(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}

/* ================= Stepper ================= */
const stepEls = document.querySelectorAll('.step');
function updateStepper() {
  const s1 = getShipments().length > 0;
  const s2 = !!exportEntry && !!goodsControl;
  const s3 = scanFiles.length > 0;
  const s4 = s3 && missingQueue.length === 0 && reviewQueue.length > 0;
  const states = [s1, s2, s3, s4];
  stepEls.forEach((el, i) => {
    el.classList.toggle('done', states[i]);
    el.classList.toggle('active', !states[i] && (i === 0 || states[i - 1]));
  });
}
updateStepper();

/* ================= Merge ================= */
const mergeStatus = document.getElementById('mergeStatus');
function setStatus(msg, cls) { mergeStatus.textContent = msg; mergeStatus.className = 'merge-status ' + (cls || ''); }

const nameModal = document.getElementById('nameModal');
const filenameInput = document.getElementById('filename');

document.getElementById('mergeBtn').addEventListener('click', () => {
  const problems = [];
  if (!exportEntry) problems.push('Export Entry PDF not attached (step 02)');
  if (!goodsControl) problems.push('Goods Control List PDF not attached (step 03)');
  if (!getShipments().length) problems.push('No shipments entered (step 01)');
  if (!scanFiles.length) problems.push('Shipment folder not scanned yet (step 04)');
  if (missingQueue.length) problems.push(`${missingQueue.length} document(s) still missing — see "Missing documents" above`);

  if (problems.length) {
    setStatus('Cannot merge yet:\n• ' + problems.join('\n• '), 'error');
    return;
  }
  filenameInput.value = 'THLC_Customs_Document_Pack';
  nameModal.classList.remove('hidden');
  filenameInput.focus();
  filenameInput.select();
});

document.getElementById('cancelModal').addEventListener('click', () => nameModal.classList.add('hidden'));
document.getElementById('confirmMerge').addEventListener('click', async () => {
  let name = filenameInput.value.trim() || 'THLC_Customs_Document_Pack';
  if (!name.toLowerCase().endsWith('.pdf')) name += '.pdf';
  nameModal.classList.add('hidden');
  await doMerge(name);
});

// Retry a flaky read a few times — cloud-synced files (OneDrive/SharePoint) that are still
// "cloud-only" placeholders can briefly fail to read while Windows fetches their content.
// This does NOT force a download (browsers have no API for that); it just gives the OS a
// few short windows to finish a download that may already be in progress.
async function readFileWithRetry(file, attempts = 3, delayMs = 700) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return new Uint8Array(await file.arrayBuffer());
    } catch (err) {
      lastErr = err;
      if (i < attempts - 1) await new Promise(r => setTimeout(r, delayMs));
    }
  }
  throw lastErr;
}

async function doMerge(outputName) {
  setStatus('Merging...');
  try {
    const { PDFDocument } = PDFLib;
    const mergedPdf = await PDFDocument.create();

    const readFailures = [];
    const loadedBytes = [];
    for (const slot of reviewQueue) {
      try {
        loadedBytes.push(await readFileWithRetry(slot.file));
      } catch (err) {
        readFailures.push(slot.label);
        missingQueue.push({ id: crypto.randomUUID(), label: slot.label });
      }
    }

    if (readFailures.length) {
      reviewQueue = reviewQueue.filter(s => !readFailures.includes(s.label));
      renderReview();
      renderMissing();
      setStatus(
        'Could not read the following file(s) — usually a OneDrive/SharePoint file still shown as ' +
        'cloud-only that has not fully downloaded to disk (a browser cannot force this download itself):\n• ' +
        readFailures.join('\n• ') +
        '\n\nOpen these files once in File Explorer to force them to download, then merge again — or use "Upload file" in the Missing documents section to pick them directly.',
        'error'
      );
      return;
    }

    for (const bytes of loadedBytes) {
      const srcPdf = await PDFDocument.load(bytes, { ignoreEncryption: true });
      const pages = await mergedPdf.copyPages(srcPdf, srcPdf.getPageIndices());
      pages.forEach(p => mergedPdf.addPage(p));
    }
    // License is never part of reviewQueue — it is always appended last, unconditionally.
    const licenseSrc = await PDFDocument.load(base64ToBytes(licenseDoc.base64), { ignoreEncryption: true });
    const licensePages = await mergedPdf.copyPages(licenseSrc, licenseSrc.getPageIndices());
    licensePages.forEach(p => mergedPdf.addPage(p));

    const mergedBytes = await mergedPdf.save();
    const blob = new Blob([mergedBytes], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = outputName;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
    setStatus(`Merged successfully — downloaded ${outputName} (${mergedPdf.getPageCount()} pages).`, 'success');
  } catch (err) {
    setStatus('Error: ' + err.message + ' (check that no file is password-protected)', 'error');
  }
}

loadLicense();
